class Task:
    def __init__(self, T_i, C_i_1, S_i, C_i_2, D_i):
        self.T_i = T_i
        self.C_i_1 = C_i_1
        self.S_i = S_i
        self.C_i_2 = C_i_2
        self.D_i = D_i # For implicit-deadline, D_i = T_i
        self.C_i = C_i_1 + C_i_2
        self.U_i = self.C_i / self.T_i

    def is_valid(self):
        # Basic feasibility checks
        if self.C_i_1 + self.S_i + self.C_i_2 > self.D_i:
            return False # Total demand exceeds deadline
        if self.U_i > 1.0:
            return False # Task utilization exceeds 100%
        return True

def calculate_task_utilization(task):
    return (task.C_i_1 + task.C_i_2) / task.T_i

def calculate_system_utilization(task_set):
    U_sum = 0
    for task in task_set:
        U_sum += calculate_task_utilization(task)
    return U_sum

def get_C_i_max(task):
    return max(task.C_i_1, task.C_i_2)

def get_C_i_min(task):
    return min(task.C_i_1, task.C_i_2)

