def dbf_i_t(task, t):
    if t < task.T_i - task.S_i:
        return 0
    else:
        # One full job's computation (C_i_1 + C_i_2)
        demand = task.C_i_1 + task.C_i_2
        # Plus additional jobs that fit in the remaining time
        remaining_time = t - (task.T_i - task.S_i)
        demand += (remaining_time // task.T_i) * (task.C_i_1 + task.C_i_2)
        return demand

def dbf_star_i_t(task, t):
    if t < task.T_i - task.S_i:
        return 0
    else:
        # One C_i_max from the first job
        demand = get_C_i_max(task)
        # Plus additional full jobs that fit in the remaining time
        remaining_time = t - (task.T_i - task.S_i)
        demand += (remaining_time // task.T_i) * (task.C_i_1 + task.C_i_2)
        return demand

def calculate_C_i_linear_approx(task):
    val1 = get_C_i_max(task)
    val2 = (task.C_i_1 + task.C_i_2) - task.U_i * task.delta_i
    return max(val1, val2)

def dbf_EDA_dagger_i_t(task, t):
    if t < task.delta_i:
        return 0
    else:
        return task.C_i_linear_approx + (t - task.delta_i) * task.U_i

def dbf_EDA_tilde_i_t(task, t):
    # For this definition, C_i_linear_approx is assumed to be task.C_i_1 + task.C_i_2
    C_i_linear_approx_val = task.C_i_1 + task.C_i_2 
    if t < task.delta_i:
        return 0
    else:
        num_periods = (t - task.delta_i) // task.T_i
        return C_i_linear_approx_val + num_periods * (task.C_i_1 + task.C_i_2)

def check_frd_necessary_condition(task_set, max_t_to_check):
    for t in range(1, max_t_to_check + 1): # Iterate over relevant interval lengths
        total_demand = 0
        for task in task_set:
            total_demand += dbf_i_t(task, t)
        if total_demand > t:
            return False # Not schedulable
    return True # Potentially schedulable (necessary condition met)

def check_arbitrary_necessary_condition(task_set, max_t_to_check):
    for t in range(1, max_t_to_check + 1):
        total_demand = 0
        for task in task_set:
            total_demand += dbf_star_i_t(task, t)
        if total_demand > t:
